import { Component } from '@angular/core';
import { DonationService } from '../../services/donation.service';

@Component({
  selector: 'app-admin-donations',
  templateUrl: './admin-donations.component.html',
  styleUrls: ['./admin-donations.component.css']
})
export class AdminDonationsComponent {

  donations: any[] = [];
  loading = true;
  errorMessage = '';

  constructor(private donationService: DonationService) {}

  ngOnInit(): void {
    this.loadDonations();
  }

  loadDonations(): void {
    this.donationService.getDonations().subscribe({
      next: (data) => {
        this.donations = data;
        this.loading = false;
      },
      error: (error) => {
        console.error(error);
        this.errorMessage = 'Unable to load donations.';
        this.loading = false;
      }
    });
  }

   updateStatus(id: number, status: string): void {

    this.donationService
      .updateDonationStatus(id, status)
      .subscribe({
        next: () => {
          this.loadDonations();
        },
        error: (error) => {
          console.error(error);
          this.errorMessage = 'Unable to update donation status.';
        }
      });
  }
}
